const CardDef& sts2CardDefFor(CardId id) {
    static CardTable table;
    int idx = (int)id >= 0 && (int)id < (int)table.byId.size() ? table.byId[(int)id] : -1;
    if (idx < 0) {
        static CardDef empty{};
        return empty;
    }
    return table.defs[idx];
}

